package net.officefloor.hq.app.invoice;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.project.Project;
import net.officefloor.hq.app.project.ProjectRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class InvoiceService {

    private final InvoiceRepository invoices;
    private final ProjectRepository projects;
    private final Audit audit;

    public InvoiceService(InvoiceRepository invoices, ProjectRepository projects, Audit audit) {
        this.invoices = invoices;
        this.projects = projects;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<InvoiceResponse> listForProject(Long projectId) {
        if (!projects.existsById(projectId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project");
        }
        return invoices.findByProjectIdOrderById(projectId).stream().map(InvoiceResponse::from).toList();
    }

    @Transactional
    public InvoiceResponse create(Long projectId, InvoiceRequest request) {
        Project project = projects.findById(projectId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project"));
        Invoice saved = invoices.save(new Invoice(project, request.amount()));
        return InvoiceResponse.from(saved);
    }

    /** Marks the invoice paid and records the payment in the audit log. */
    @Transactional
    public InvoiceResponse pay(Long projectId, Long invoiceId) {
        Invoice invoice = invoices.findById(invoiceId)
                .filter(i -> i.getProject().getId().equals(projectId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
        if (invoice.getStatus() == InvoiceStatus.PAID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Invoice is already paid");
        }
        invoice.markPaid();
        invoices.flush();
        audit.record("INVOICE_PAID id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
        return InvoiceResponse.from(invoice);
    }
}
package net.officefloor.hq.app.invoice;

/** Payment state of an invoice. */
public enum InvoiceStatus {
    UNPAID,
    PAID
}
CREATE TABLE invoice (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT         NOT NULL,
    amount     DECIMAL(12, 2) NOT NULL,
    CONSTRAINT invoice_project_fk FOREIGN KEY (project_id) REFERENCES project (id),
    CONSTRAINT invoice_amount_positive CHECK (amount > 0)
);

CREATE INDEX invoice_project_idx ON invoice (project_id);
ALTER TABLE invoice ADD COLUMN status VARCHAR(16) DEFAULT 'UNPAID' NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_status_valid CHECK (status IN ('UNPAID', 'PAID'));
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export type InvoiceStatus = 'UNPAID' | 'PAID';

export interface Invoice {
  id: number;
  projectId: number;
  amount: number;
  status: InvoiceStatus;
}

export interface NewInvoice {
  amount: number;
}

@Injectable({ providedIn: 'root' })
export class InvoiceService {
  private readonly http = inject(HttpClient);

  listForProject(projectId: number): Observable<Invoice[]> {
    return this.http.get<Invoice[]>(`/api/projects/${projectId}/invoices`);
  }

  create(projectId: number, invoice: NewInvoice): Observable<Invoice> {
    return this.http.post<Invoice>(`/api/projects/${projectId}/invoices`, invoice);
  }

  pay(projectId: number, invoiceId: number): Observable<Invoice> {
    return this.http.post<Invoice>(`/api/projects/${projectId}/invoices/${invoiceId}/pay`, null);
  }
}
import { CurrencyPipe } from '@angular/common';
import { Component, computed, inject, input, signal } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { InvoiceService } from './invoice.service';

// A project's invoices: lists them, shows what they add up to, adds a new one by amount, and marks
// one as paid.
@Component({
  selector: 'app-project-invoices',
  imports: [ReactiveFormsModule, CurrencyPipe],
  template: `
    <section aria-labelledby="project-invoices-heading" data-testid="project-invoices">
      <h2 id="project-invoices-heading">Invoices</h2>

      <form [formGroup]="form" (ngSubmit)="submit()" data-testid="invoice-form" novalidate>
        <div>
          <label for="invoice-amount">Amount</label>
          <input
            id="invoice-amount"
            type="number"
            inputmode="decimal"
            min="0.01"
            step="0.01"
            formControlName="amount"
            data-testid="invoice-form-amount"
            [attr.aria-invalid]="showError()"
            [attr.aria-describedby]="showError() ? 'invoice-amount-error' : null"
          />
          @if (showError()) {
            <p id="invoice-amount-error" role="alert" data-testid="invoice-form-amount-error">
              Enter an amount greater than zero with at most two decimal places.
            </p>
          }
        </div>
        <button type="submit" data-testid="invoice-form-submit" [disabled]="saving()">
          Add invoice
        </button>
        @if (saveError()) {
          <p role="alert" data-testid="invoice-form-error">{{ saveError() }}</p>
        }
      </form>

      @if (invoices.error()) {
        <p role="alert" data-testid="project-invoices-error">Could not load the invoices.</p>
      } @else if (list().length === 0) {
        <p data-testid="project-invoices-empty">No invoices yet.</p>
      } @else {
        <table data-testid="project-invoices-table">
          <caption>Invoices for this project</caption>
          <thead>
            <tr>
              <th scope="col">Invoice</th>
              <th scope="col">Amount</th>
              <th scope="col">Status</th>
              <th scope="col"><span class="visually-hidden">Actions</span></th>
            </tr>
          </thead>
          <tbody>
            @for (i of list(); track i.id) {
              <tr [attr.data-testid]="'invoice-row-' + i.id">
                <td data-testid="invoice-id">#{{ i.id }}</td>
                <td data-testid="invoice-amount">{{ i.amount | currency: 'USD' : 'symbol' : '1.2-2' : 'en-US' }}</td>
                <td data-testid="invoice-status">{{ i.status }}</td>
                <td>
                  @if (i.status === 'UNPAID') {
                    <button
                      type="button"
                      [attr.data-testid]="'invoice-pay-' + i.id"
                      [attr.aria-label]="'Mark invoice #' + i.id + ' as paid'"
                      [disabled]="paying() === i.id"
                      (click)="pay(i.id)"
                    >
                      Mark paid
                    </button>
                  }
                </td>
              </tr>
            }
          </tbody>
          <tfoot>
            <tr>
              <th scope="row">Total</th>
              <td data-testid="project-invoices-total">{{ totalCents() / 100 | currency: 'USD' : 'symbol' : '1.2-2' : 'en-US' }}</td>
              <td colspan="2"></td>
            </tr>
          </tfoot>
        </table>
        @if (payError()) {
          <p role="alert" data-testid="invoice-pay-error">{{ payError() }}</p>
        }
      }
    </section>
  `,
})
export class ProjectInvoices {
  private readonly service = inject(InvoiceService);

  readonly projectId = input.required<number>();

  protected readonly invoices = rxResource({
    params: () => this.projectId(),
    stream: ({ params }) => this.service.listForProject(params),
  });
  protected readonly list = computed(() => (this.invoices.hasValue() ? this.invoices.value() : []));
  // Sum in whole cents so the total is exact rather than accumulating floating-point error.
  protected readonly totalCents = computed(() =>
    this.list().reduce((sum, i) => sum + Math.round(i.amount * 100), 0),
  );

  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);

  protected readonly paying = signal<number | null>(null);
  protected readonly payError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group({
    amount: [
      '',
      [Validators.required, Validators.min(0.01), Validators.pattern(/^\d+(\.\d{1,2})?$/)],
    ],
  });

  protected showError(): boolean {
    const control = this.form.controls.amount;
    return control.invalid && (control.touched || control.dirty);
  }

  protected submit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    this.saving.set(true);
    this.saveError.set(null);
    const amount = Number(this.form.getRawValue().amount);
    this.service.create(this.projectId(), { amount }).subscribe({
      next: (created) => {
        this.invoices.update((list) => [...(list ?? []), created]);
        this.form.reset();
        this.saving.set(false);
      },
      error: () => {
        this.saveError.set('Could not save the invoice. Please try again.');
        this.saving.set(false);
      },
    });
  }

  protected pay(invoiceId: number): void {
    this.paying.set(invoiceId);
    this.payError.set(null);
    this.service.pay(this.projectId(), invoiceId).subscribe({
      next: (paid) => {
        this.invoices.update((list) => (list ?? []).map((i) => (i.id === paid.id ? paid : i)));
        this.paying.set(null);
      },
      error: () => {
        this.payError.set('Could not mark the invoice as paid. Please try again.');
        this.paying.set(null);
      },
    });
  }
}

